cd /tmp/vally-eval-trial-Vb90KB && cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class Checkout
{
    public decimal CalculatePayableTotal(string customerTier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.IntegrationTests;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_00_subtotal_pays_95_00()
    {
        var payable = new Checkout().CalculatePayableTotal("Gold", 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | grep -v warning | tail -25

